const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateIST=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const types=REPORT_NAMES.filter(t=>!['Employee Task','Boiler Hourly Log','Boiler Water Tests'].includes(t));
let state=null,token=sessionStorage.getItem('starish-session')||'',tab='Overview',reportType='Boardline Production',page=0,search='',busy=false,timer,installPrompt,taskView='all',taskEmployee='',taskEmployeeSearch='',routineSelected=new Set(),routineEmployeeSearch='',routineAssignee='',routineDue='',tableMode='daily',analysisMetric='',analysisCategory='',analysisChart='bar',analysisPeriod='Month',taskReportEmployeeSearch='';
const plant=()=>state&&state.user.email==='pariklupin@gmail.com';
const admin=()=>state&&['Owner','Plant Head'].includes(state.user.role);
const taskManager=()=>admin()||!!(state?.user?.managedDepartments||[]).length;
const departmentManager=()=>!!(state?.user?.managedDepartments||[]).length;
const canCreateDepartment=()=>admin()||(state?.user?.managedDepartments||[]).includes('*');
const manageComplaints=()=>!!state&&(admin()||state.user.role==='Maintenance Head');
const raiseComplaints=()=>!!state&&(manageComplaints()||(state.user.entryTypes||[]).includes('Maintenance Complaint'));
const workComplaints=()=>!!state&&/maint/i.test(String(state.user.department||''))&&state.user.role!=='Maintenance Head'&&!admin();
const useComplaints=()=>manageComplaints()||raiseComplaints()||workComplaints();
const allComplaints=()=>{const rows=[...(state.complaints||[]),...(state.myComplaints||[]),...(state.assignedComplaints||[])];return [...new Map(rows.map(c=>[c.tokenNo,c])).values()].sort((a,b)=>String(b.raisedAt).localeCompare(String(a.raisedAt)));};
const badge=s=>`<span class="badge ${s==='Approved'||s==='Closed'?'approved':''}">${esc(s||'Not reviewed')}</span>`;
const overdue=t=>!['Submitted','Closed','Removed'].includes(t.status)&&Date.parse(t.due)<Date.now();
const employeeOptions=selected=>`<option value="">Select employee</option>`+(state.users||[]).filter(u=>u.active).map(u=>`<option value="${esc(u.email)}" ${u.email===selected?'selected':''}>${esc(u.name)} (${esc(u.loginEmail||u.phone||u.email)})</option>`).join('');
const option=(list,value)=>list.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('');
if(localStorage.getItem('portal-nav-hidden')==='true')document.body.classList.add('nav-collapsed');
function updateFullScreenLabel(){const b=$('#fullscreenTable');if(b)b.textContent=document.fullscreenElement||document.querySelector('#content .excel-report.table-fullscreen')?'Exit full screen':'Full screen table';}
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)document.querySelectorAll('.table-fullscreen-close').forEach(b=>b.remove());updateFullScreenLabel();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const target=document.querySelector('#content .excel-report.table-fullscreen');if(target)target.classList.remove('table-fullscreen');updateFullScreenLabel();}});
function bindLayoutControls(){
 const nav=$('#toggleNav');
 if(nav){const hidden=document.body.classList.contains('nav-collapsed');nav.textContent=hidden?'Show navigation':'Hide navigation';nav.setAttribute('aria-expanded',String(!hidden));nav.onclick=()=>{const isHidden=document.body.classList.toggle('nav-collapsed');localStorage.setItem('portal-nav-hidden',String(isHidden));nav.textContent=isHidden?'Show navigation':'Hide navigation';nav.setAttribute('aria-expanded',String(!isHidden));};}
 const full=$('#fullscreenTable'),target=$('#content .excel-report');
 if(full){full.hidden=!target;full.onclick=async()=>{const panel=$('#content .excel-report');if(!panel)return;if(document.fullscreenElement){await document.exitFullscreen();return;}if(panel.classList.contains('table-fullscreen')){panel.classList.remove('table-fullscreen');updateFullScreenLabel();return;}try{if(!panel.requestFullscreen)throw Error('Fullscreen unavailable');await panel.requestFullscreen();const close=document.createElement('button');close.type='button';close.className='secondary table-fullscreen-close';close.textContent='Exit full screen';close.onclick=()=>document.exitFullscreen();panel.prepend(close);}catch{panel.classList.add('table-fullscreen');const close=document.createElement('button');close.type='button';close.className='secondary table-fullscreen-close';close.textContent='Exit full screen';close.onclick=()=>{panel.classList.remove('table-fullscreen');updateFullScreenLabel();};panel.prepend(close);}updateFullScreenLabel();};}
 updateFullScreenLabel();
}

function message(s){$('#message').textContent=s;$('#message').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#message').hidden=true,8000);}
function renderIdentity(){const count=(state?.notifications||[]).filter(n=>!n.read).length;$('#identity').innerHTML=`<span>${esc(state?.user?.name||'')}</span><button id="notificationCount" class="notification-count" type="button" title="Open notifications" aria-label="${count} unread notifications">${count}</button>`;$('#notificationCount').onclick=()=>{tab='Notifications';page=0;render();};}
function api(action,data={},mutation=false){const url=window.PORTAL_CONFIG?.apiUrl;
 if(!/^https:\/\/script\.google\.com\/macros\/s\/[a-zA-Z0-9_-]+\/exec$/.test(url||''))return Promise.reject(Error('Set the NEW portal Apps Script URL in config.js first.'));
 if(!navigator.onLine)return Promise.reject(Error('Internet is required to read or save data.'));
 const nonce=Array.from(crypto.getRandomValues(new Uint8Array(24)),v=>v.toString(16).padStart(2,'0')).join(''),requestId=crypto.randomUUID();
 return new Promise((resolve,reject)=>{const frame=document.createElement('iframe'),form=document.createElement('form'),input=document.createElement('input');frame.name='api_'+nonce;frame.hidden=true;form.hidden=true;form.method='POST';form.action=url;form.target=frame.name;input.type='hidden';input.name='payload';input.value=JSON.stringify({action,data,token,nonce,requestId,origin:location.origin});form.append(input);
 const timeout=setTimeout(()=>finish(Error(mutation?'Save confirmation timed out. Refresh and check the record before retrying.':'The portal server is taking too long. Check your internet and try again.')),90000);
 function receive(e){let host;try{const u=new URL(e.origin);if(u.protocol!=='https:')return;host=u.hostname;}catch{return;}
 if(!(host==='script.google.com'||host==='script.googleusercontent.com'||host.endsWith('.googleusercontent.com')))return;
 if(e.data?.channel!=='starish-api'||e.data.nonce!==nonce)return;
 if(e.data.result?.ok)finish(null,e.data.result);else finish(Error(e.data.result?.error||'Request failed'));
 }
 function finish(error,result){clearTimeout(timeout);window.removeEventListener('message',receive);form.remove();frame.remove();error?reject(error):resolve(result);}
 window.addEventListener('message',receive);document.body.append(frame,form);form.submit();
 });
}
async function load(){if(busy)return;busy=true;$('#refresh').disabled=true;const oldLabel=$('#refresh').textContent;$('#refresh').textContent='Loading…';if(!state&&token){$('#login').hidden=true;$('#shell').hidden=false;$('#content').innerHTML='<div class="card">Loading your reports and tasks…</div>';}try{const r=await api('workspace',{from:$('#from').value,to:$('#to').value});state=r;$('#login').hidden=true;$('#shell').hidden=false;$('#logout').hidden=false;$('#identity').textContent=r.user.name;render();}catch(e){if(/Login expired|Account inactive/.test(e.message))signoutLocal();else if(!state&&token)$('#content').innerHTML=`<div class="card"><b>Reports and tasks could not be loaded.</b><p>${esc(e.message)}</p><button id="retryLoad">Try again</button></div>`;message(e.message);}finally{busy=false;$('#refresh').disabled=false;$('#refresh').textContent=oldLabel;const retry=$('#retryLoad');if(retry)retry.onclick=load;}}
function reportPermission(cap,type){if(cap==='entry'&&['Glue Consumption','Stage Report','Employee Task'].includes(type))return false;if(cap==='entry'&&['Boiler','Boiler Hourly Log','Boiler Water Tests'].includes(type))return plant()||(!admin()&&(state.user.entryTypes||[]).includes(type));if((cap==='correct'||cap==='delete')&&['Glue Consumption','Employee Task'].includes(type))return false;if(admin())return true;const key={view:'forms',entry:'entryTypes',correct:'editTypes',delete:'deleteTypes'}[cap];return !!key&&(state.user[key]||[]).includes(type);}
function visibleTypes(){return admin()?types:types.filter(t=>reportPermission('view',t)||t==='Glue Consumption'&&reportPermission('view','Glue Kitchen Stock'));}
function filtered(){const shift=$('#shift').value,review=$('#review').value;return state.reports.filter(r=>(reportType==='Glue Consumption'&&tab==='Reports'||shift==='All'||r.shift===shift)&&(review==='All statuses'||(review==='Approved'?r.status==='Approved':r.status!=='Approved')));}
function render(){document.body.classList.toggle('owner-compact',state.user.role==='Owner');renderIdentity();if(admin()&&tab==='Overview')tab='Reports';if(state.user.role==='Maintenance Head'&&tab==='Overview')tab='Maintenance Complaints';const permitted=state.user.sections||['Reports','Tasks','Analysis','Notifications','My account'];const tabs=admin()?['Reports','Tasks','Analysis']:permitted.filter(t=>t!=='Notifications');if(taskManager()){const taskTabIndex=tabs.indexOf('Tasks');tabs.splice(taskTabIndex<0?0:taskTabIndex+1,0,'Department Management');}else if((state.departmentSops||[]).length)tabs.push('Department SOP');if(plant())tabs.push('Task report');if(plant()||reportPermission('entry','Boiler'))tabs.push('Boiler Entry');if(plant())tabs.push('User Access');if(useComplaints())tabs.push('Maintenance Complaints');if(!tabs.includes(tab)&&!['Notifications','Employees','Daily routines','Sources','Department Management','Department SOP','Task report'].includes(tab))tab=tabs[0]||'My account';$('#nav').innerHTML=tabs.map(t=>`<button data-tab="${esc(t)}" class="${tab===t?'active':''}">${esc(t==='Department Management'?'Departments':t)}</button>`).join('');$('#pageTitle').textContent=tab;$('#filters').hidden=!['Overview','Reports','Analysis'].includes(tab);let html='';
 if(tab==='Overview'){const t=scopedTasks().filter(t=>t.status!=='Removed');html=`${admin()?'<div class="toolbar"><button data-new-task>+ Assign task</button></div>'+taskEmployeePicker():''}<div class="kpis">${[['Pending tasks',t.filter(t=>!['Submitted','Closed'].includes(t.status)).length,'pending'],['Completed tasks',t.filter(t=>['Submitted','Closed'].includes(t.status)).length,'completed'],['Assigned tasks',t.filter(t=>taskKind(t)==='assigned').length,'assigned'],['Overdue',t.filter(overdue).length,'overdue']].map(([label,n,view])=>`<button class="card" data-task-view="${view}"><small>${label}</small><strong>${n}</strong><small>Tap to view</small></button>`).join('')}${admin()?`<button class="card" data-task-view="removal"><small>Removal approval requests</small><strong>${t.filter(t=>t.removalRequest?.status==='Requested').length}</strong><small>Tap to review</small></button>`:''}</div>${admin()&&taskView!=='all'?employeeTaskOverview():''}<h2>Report summary · ${esc($('#from').value)} to ${esc($('#to').value)}</h2><div class="grid">${visibleTypes().map(type=>`<button class="summary-card" data-type="${esc(type)}"><small>${type.includes('Production')?'EXISTING SOURCE':type==='Glue Consumption'?'CALCULATED':'REPORT'}</small><h2>${esc(type)}</h2>${summary(type,filtered(),state.batchChangeover).slice(0,3).map(m=>`<div class="metric"><span>${esc(m.label)}</span><b>${esc(m.value)}</b></div>`).join('')}<span class="link">View details & inquiry →</span></button>`).join('')}</div>`;}
 if(tab==='Reports')html=admin()?simpleReportsHtml():reportsHtml();
 if(tab==='Boiler Entry')html=boilerEntryHtml();
 if(tab==='Analysis')html=analysisHtml();
 if(tab==='Tasks')html=allTaskViewer()?simpleTasksHtml():tasksHtml();
 if(tab==='Department Management')html=departmentManagementHtml();
 if(tab==='Department SOP')html=departmentSopHtml();
 if(tab==='Task report')html=taskReportHtml();
 if(tab==='Maintenance Complaints')html=complaintBoardHtml();
 if(tab==='Notifications')html=`<div class="card">${state.notifications.map(n=>`<div class="history"><b>${esc(n.title)}</b><small>${esc(new Date(n.at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</small><div class="form-actions">${n.taskId?`<button data-task="${esc(n.taskId)}">View task</button>`:''}${n.reportId?`<button data-report="${esc(n.reportId)}">View report</button>`:''}${!n.read?`<button class="secondary" data-read="${esc(n.id)}">Mark read</button>`:'<small>Read</small>'}</div></div>`).join('')||'<div class="empty">No notifications yet.</div>'}</div>`;
 if(tab==='My account')html=`<div class="card"><h2>Mobile + PIN login</h2><p>Registered email: ${esc(state.user.loginEmail||'Not set')}<br>Mobile: ${esc(state.user.phone||'Not set')}</p><p class="muted">Email OTP stays available if your account has an email. Register your mobile and set a private 6–12 digit PIN here. PIN changes sign out other existing sessions.</p><button id="changePin">Set / change my mobile PIN</button></div>`;
 if(tab==='Employees'||tab==='User Access'){const employees=matchingEmployees(state.employees,search);html=`<div class="toolbar"><button data-new-employee>+ Add employee</button><input id="employeeSearch" type="search" placeholder="Search employee name / department / email / mobile" aria-label="Search employees" value="${esc(search)}"><small>${employees.length} of ${state.employees.length} employees</small></div><p class="muted">Add login email/mobile and form permissions. Owner account is configured separately.</p><div class="card table-wrap"><table><thead><tr><th>Name</th><th>Department</th><th>Email / mobile / access</th><th>Action</th></tr></thead><tbody>${employees.map(e=>`<tr><td>${esc(e.name)}</td><td>${esc(e.department)}</td><td>${esc(e.email||'Email not set')}<small>${esc(e.phone||'Mobile not set')}</small><small>${esc((e.managedDepartments||[]).length?'Department Manager':' '+(e.role||'Employee'))} · ${e.active?'Active':'Inactive'} · ${esc((e.forms||[]).join(', '))}</small>${(e.managedDepartments||[]).length?`<small>Manages: ${esc(e.managedDepartments.includes('*')?'All departments':e.managedDepartments.join(', '))}</small>`:''}</td><td><button data-employee="${esc(e.id)}">Configure</button>${plant()?`<button class="danger" data-delete-employee="${esc(e.id)}">Remove employee</button>`:''}</td></tr>`).join('')}</tbody></table>${!employees.length?'<div class="empty">'+(state.employees.length?'No matching employee. Try another name or department.':'No employees added yet.')+'</div>':''}</div>`;}
 if(tab==='Daily routines')html=routinesHtml();
 if(tab==='Sources')html=`<div class="toolbar"><button data-new-source>+ Connect report Sheet</button><button class="secondary" id="sync">Sync enabled sources</button></div><p class="notice">Production Planning / Dispatch is preconfigured for read-only daily sync from the Dispatch tab. It imports invoice, customer, vehicle, product, quantity and amount; weighbridge net stays blank because that tab has no such column. Its PDF shows totals and a customer-wise summary. Existing entry apps stay unchanged. Connect source Sheet tabs and exact column mappings. Loading source is preconfigured but disabled until you enable it. Stage report calculation remains in the existing PC workflow; this portal reads the resulting STAGE_TIME data.</p><div class="card table-wrap"><table><thead><tr><th>Source</th><th>Enabled</th><th>Last sync</th><th>Action</th></tr></thead><tbody>${state.sources.map(s=>{const st=state.syncStatus.find(x=>x.id===s.id);return `<tr><td>${esc(s.name)}<small>${esc(s.kind==='loading'?'Loading + Stage':s.type+' / '+s.tab)}</small></td><td>${s.enabled?'Yes':'No'}</td><td>${st?esc(st.lastSuccess||'No successful sync')+`<small>${st.rows||0} rows · ${esc(st.error||'OK')}</small>`:'Not synced'}</td><td><button data-source="${esc(s.id)}">Configure</button></td></tr>`;}).join('')}</tbody></table></div>`;
 $('#content').innerHTML=html;const chooser=$('#reportChooser');if(chooser)chooser.innerHTML=(admin()&&tab==='Reports'||tab==='Analysis')?`<label>Report<select id="reportType">${option(visibleTypes(),reportType)}</select></label>`:'';bindLayoutControls();bindContent();}

function complaintBoardHtml(){
 const rows=allComplaints().filter(c=>JSON.stringify(c).toLowerCase().includes(search.toLowerCase()));
 return `${raiseComplaints()?'<div class="toolbar"><button data-new-complaint>+ Raise complaint</button></div>':''}<div class="card table-wrap"><table><thead><tr><th>Token</th><th>Machine / unit</th><th>Issue</th><th>Priority</th><th>Status</th><th>Assigned to</th><th>Work hours</th><th>Action</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${esc(c.tokenNo)}<small>${esc(new Date(c.raisedAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</small></td><td>${esc(c.machine)}<small>${esc(c.unit||'')}</small></td><td>${esc(c.issueType)}<small>${esc(c.description)}</small></td><td>${esc(c.priority)}</td><td>${badge(c.status)}${c.workRunning?'<small>Timer running</small>':''}</td><td>${esc(c.assignedTo||'Unassigned')}</td><td>${Number(c.workingHours||0).toFixed(2)}</td><td>${manageComplaints()&&c.status!=='Closed'?'<button data-complaint-assign="'+esc(c.tokenNo)+'">Assign</button>':''}${workComplaints()&&c.status!=='Closed'?(c.workRunning?'<button data-complaint-work="'+esc(c.tokenNo)+'">Update work</button>':['Assigned','Waiting for Spares'].includes(c.status)?'<button data-complaint-start="'+esc(c.tokenNo)+'">Start / resume</button>':''):''}<button class="secondary" data-complaint-detail="${esc(c.tokenNo)}">Details</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">No complaints yet.</div>'}</div>`;
}
function complaintDetails(c){modal('Complaint '+c.tokenNo,`<p>${badge(c.status)} · ${esc(c.priority)}</p><p><b>${esc(c.machine)} ${esc(c.unit||'')}</b><br>${esc(c.issueType)} · ${esc(c.description)}</p><p>Raised by ${esc(c.reportedBy)}<br>Assigned to ${esc(c.assignedTo||'Not assigned')}<br>Working hours: ${Number(c.workingHours||0).toFixed(2)}</p>${c.workDone?'<div class="history"><b>Work done</b><p>'+esc(c.workDone)+'</p></div>':''}${c.sparesProcured?'<div class="history"><b>Spares</b><p>'+esc(c.sparesProcured)+'</p></div>':''}${c.maintenanceRemarks?'<div class="history"><b>Remarks</b><p>'+esc(c.maintenanceRemarks)+'</p></div>':''}`);}
function complaintForm(){modal('Raise maintenance complaint',`<form id="complaintForm"><div class="form-grid"><label>Machine name<input name="machine" required></label><label>Unit / part<input name="unit"></label><label>Issue type<select name="issueType">${option(['Electrical','Mechanical','Other'],'Mechanical')}</select></label><label>Priority<select name="priority">${option(['Normal','Urgent'],'Normal')}</select></label><label>Job card / Posting No.<input name="postingNo"></label><label class="full">Issue description<textarea name="description" required></textarea></label></div><p class="muted">Maintenance Head assigns a technician and verifies spares.</p><div class="form-actions"><button type="submit">Submit complaint</button></div></form>`);submit($('#complaintForm'),async fd=>{await mutate('saveComplaint',{machine:fd.get('machine'),unit:fd.get('unit'),issueType:fd.get('issueType'),priority:fd.get('priority'),postingNo:fd.get('postingNo'),description:fd.get('description')});message('Complaint sent to Maintenance Head');});}
function assignComplaintForm(c){modal('Assign '+c.tokenNo,'<form id="complaintAssignForm"><label>Maintenance employee<select name="assignedTo" required><option value="">Choose employee</option>'+(state.complaintOptions?.maintenanceStaff||[]).map(x=>'<option value="'+esc(x.email)+'">'+esc(x.name)+'</option>').join('')+'</select></label><p class="muted">Work timer starts when the assigned employee presses Start / Resume.</p><div class="form-actions"><button type="submit">Assign complaint</button></div></form>');submit($('#complaintAssignForm'),async fd=>{await mutate('assignComplaint',{tokenNo:c.tokenNo,updatedAt:c.updatedAt,assignedTo:fd.get('assignedTo')});message('Complaint assigned');});}
function startComplaint(tokenNo){const c=allComplaints().find(x=>x.tokenNo===tokenNo);if(c)mutate('startComplaintWork',{tokenNo:c.tokenNo,updatedAt:c.updatedAt}).then(()=>message('Work timer started')).catch(e=>message(e.message));}
function complaintWorkForm(c){modal('Work update · '+c.tokenNo,`<form id="complaintWorkForm"><label>Spare status<select name="sparesStatus">${option(['Not checked','Available','Not available','Not required'],c.sparesStatus||'Not checked')}</select></label><label>Pause status<select name="status">${option(['Assigned','Waiting for Spares'],c.status==='Waiting for Spares'?'Waiting for Spares':'Assigned')}</select></label><label>Spare procured / used<input name="sparesProcured" value="${esc(c.sparesProcured)}"></label><label>Work done / action taken<textarea name="workDone">${esc(c.workDone)}</textarea></label><label>Maintenance remarks<textarea name="maintenanceRemarks">${esc(c.maintenanceRemarks)}</textarea></label><p class="muted">Paused time is excluded. Each work session is written to Maintenance Timesheet.</p><div class="form-actions"><button type="submit" name="mode" value="pause" class="secondary">Save & pause</button><button type="submit" name="mode" value="complete">Complete</button></div></form>`);$('#complaintWorkForm').onsubmit=async e=>{e.preventDefault();const f=e.target,b=e.submitter,fd=new FormData(f),data={tokenNo:c.tokenNo,updatedAt:c.updatedAt,sparesStatus:fd.get('sparesStatus'),maintenanceRemarks:fd.get('maintenanceRemarks')};b.disabled=true;try{if(b.value==='pause'){data.status=fd.get('status');await mutate('pauseComplaintWork',data);message('Paused time added to Maintenance Timesheet');}else{data.sparesProcured=fd.get('sparesProcured');data.workDone=fd.get('workDone');await mutate('completeComplaintWork',data);message('Complaint closed; final work time added to Maintenance Timesheet');}}catch(err){message(err.message);}finally{b.disabled=false;}};}
function bindComplaintActions(){document.querySelectorAll('[data-new-complaint]').forEach(b=>b.onclick=complaintForm);document.querySelectorAll('[data-complaint-assign]').forEach(b=>b.onclick=()=>{const c=allComplaints().find(x=>x.tokenNo===b.dataset.complaintAssign);if(c)assignComplaintForm(c);});document.querySelectorAll('[data-complaint-start]').forEach(b=>b.onclick=()=>startComplaint(b.dataset.complaintStart));document.querySelectorAll('[data-complaint-work]').forEach(b=>b.onclick=()=>{const c=allComplaints().find(x=>x.tokenNo===b.dataset.complaintWork);if(c)complaintWorkForm(c);});document.querySelectorAll('[data-complaint-detail]').forEach(b=>b.onclick=()=>{const c=allComplaints().find(x=>x.tokenNo===b.dataset.complaintDetail);if(c)complaintDetails(c);});}

function pagination(pages){return `<div class="pagination"><button class="secondary" data-page="-1" ${page===0?'disabled':''}>Previous</button><small>Page ${page+1} / ${pages}</small><button class="secondary" data-page="1" ${page>=pages-1?'disabled':''}>Next</button></div>`;}
function reportsHtml(){const available=visibleTypes();if(!available.includes(reportType))reportType=available[0]||'';const entries=filtered().filter(r=>r.type===reportType&&JSON.stringify(r.fields).toLowerCase().includes(search.toLowerCase()));const model=buildReportTable(reportType,entries,{mode:'daily',changeover:state.batchChangeover,visibleColumns:state.reportColumns?.[reportType]}),pages=Math.max(1,Math.ceil(model.rows.length/30));page=Math.min(page,pages-1);
const html=`${reportKpisHtml()}<div class="toolbar"><select id="reportType">${option(available,reportType)}</select><button id="pdf" class="secondary">Download PDF</button>${reportPermission('entry',reportType)?'<button id="newReport">+ New entry</button>':''}<input id="reportSearch" placeholder="Search details" value="${esc(search)}"></div><div class="kpis">${summary(reportType,filtered(),state.batchChangeover).filter(m=>!/review|approval/i.test(m.label)).slice(0,reportType==='Water Meter'?Infinity:4).map(m=>`<div class="card"><small>${esc(m.label)}</small><strong style="font-size:20px">${esc(m.value)}</strong></div>`).join('')}</div>`;
return html+`<div class="card table-wrap excel-report"><h2>${esc(model.caption)}</h2><table><thead><tr>${model.columns.map(k=>'<th>'+esc(k)+'</th>').join('')}<th>Action</th></tr></thead><tbody>${model.rows.slice(page*30,page*30+30).map(row=>`<tr>${model.columns.map(k=>'<td>'+esc(row.values[k]??'')+'</td>').join('')}<td>${row.id?`<button data-report="${esc(row.id)}">Open details</button>`:row.recordIds?.length?`<button data-group-reports="${esc(row.recordIds.join(','))}">Details</button>`:''}</td></tr>`).join('')}</tbody>${model.totals?'<tfoot><tr>'+model.columns.map(k=>'<td>'+esc(model.totals[k]??'')+'</td>').join('')+'<td></td></tr></tfoot>':''}</table>${model.rows.length?pagination(pages):'<p class="empty">No records in this range.</p>'}</div>`;}
