function searchChange(e,id){const pos=e.target.selectionStart;search=e.target.value;page=0;render();const el=$('#'+id);el.focus();if(el.type!=='search'&&pos!==null)el.setSelectionRange(pos,pos);}
function modal(title,html){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();}
async function mutate(action,data={}){const r=await api(action,data,true);$('#dialog').close();void load();return r;}
function submit(form,fn){form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button[type=submit]')||form.querySelector('button');if(b.disabled)return;const label=b.textContent;let status=form.querySelector('[data-save-status]');if(!status){status=document.createElement('p');status.dataset.saveStatus='';status.setAttribute('role','status');status.setAttribute('aria-live','polite');form.append(status);}status.textContent='Saving… Please wait for confirmation.';b.disabled=true;b.textContent='Saving…';try{await fn(new FormData(form));status.textContent='Successfully saved';}catch(err){status.textContent=err.message==='Unknown action'?'Apps Script backend needs the latest Code.gs. Deploy > Manage deployments > Edit > New version > Deploy, then retry.':err.message;message(status.textContent);}finally{b.disabled=false;b.textContent=label;}};}
function inputField(k,value='',type=reportType){if(type==='Maintenance Timesheet'&&['Employee Name','Machine'].includes(k)){const choices=k==='Employee Name'?(state.maintenanceOptions?.employees||[]):["Auto Stitching & Gluing","Auto folder","Auto folder & gluer machine","B Flute","Board line","Chain Feeder Printing","Diesel generator","Double Backer","EL machine","Forklift","Glue kitchen","Grease gun","Hand trolley","Hot plate","Jf printing","Manual strapping machine","Security gate","Semiauto stitching machine","Slitter scorer","Slitter square machine","Smartcech printing"],known=choices.includes(value),custom=!known&&!!value,selected=custom?'__other__':value;return `<label>${esc(k)}<select name="${esc(k)}" data-maintenance-select="${esc(k)}" required><option value="">Choose ${k.toLowerCase()}</option>${option(choices,selected)}<option value="__other__" ${custom?'selected':''}>Other — enter manually</option></select><input name="${esc(k)}__custom" data-maintenance-custom="${esc(k)}" placeholder="Type ${k.toLowerCase()}" value="${custom?esc(value):''}" ${custom?'required':''} ${custom?'':'hidden'}></label>`;}let options=k==='Material Name'?MATERIALS:k==='Meter Name'?METERS:k==='Stock Unit'?['Bags','kg','litres','Nos']:k==='Container Type'?['Can','Barrel']:k==='Used For'?['DG','Forklift']:k==='Status'?['Pending','In progress','Completed']:null;const optional=['Steam Pressure (bar)','Feed Water Temperature (C)','Flue Gas T1 (C)','Flue Gas T2 (C)','Test Time','Fuel Meter Reading','Steam Meter Reading','Calculated Water (litres)','Calculated Fuel (kg)','Calculated Steam (kg)','Reading Day Offset','Hardness (ppm)','Breakdown Reason','Reason','Colour Changes','Starch per Bag (kg)','Starch per Batch (kg)'].includes(k);return `<label>${esc(k)}${options?`<select name="${esc(k)}">${option(options,value||options[0])}</select>`:`<input name="${esc(k)}" type="${inputType(k)}" ${inputType(k)==='number'?'min="0" step="any"':''} value="${esc(value)}" ${optional?'':'required'}>`}</label>`;}
function entryForm(r){const type=r?.type||reportType;if(!reportPermission(r?'correct':'entry',type))return message(r?'Correction permission required':'Entry form permission required');if(!r&&type==='Boiler'){tab='Boiler Entry';boilerEntryType=reportType;render();return;}const fields=r?.fields||{},date=r?.date||dateIST();modal(r?'Correct '+type:'New '+type,`<form id="entryForm"><div class="form-grid"><label>Date<input name="date" type="date" value="${date}" required></label><label>Shift<select name="shift">${option(['Day','Night','Daily'],r?.shift||'Daily')}</select></label>${fieldNames(type).filter(k=>(type!=='DG Operation'||k!=='Diesel Consumption (litres)')&&(type!=='Diesel Consumption'||k!=='Issued Litres')).map(k=>inputField(k,fields[k]??(k==='Employee Name'&&type==='Maintenance Timesheet'?state.user.name:k==='Reading Multiplier'?'1':k==='Starch per Bag (kg)'?'50':k==='Starch per Batch (kg)'?(date<'2026-09-10'?'200':'150'):''),type)).join('')}${type==='Water Meter'?'<p id="waterOpeningNote" class="full notice">Opening reading will be fetched from the previous meter closing.</p>':''}${type==='Diesel Consumption'?'<p class="full notice">Enter Can and Barrel counts for Opening, Receiving and Issue. 1 Can = 35 litres; 1 Barrel = 200 litres. Enter 0 where none. Save a separate entry for each receiver/use. Reports show litres. <strong id="dieselIssue"></strong></p>':''}${type==='DG Operation'?'<p class="full notice">Fixed diesel rate: 26 litres/hour. Enter duration as HH:MM (01:30 = 1 hour 30 minutes). <strong id="dgConsumption"></strong></p>':''}<label class="full">Remarks<textarea name="Remarks">${esc(fields.Remarks)}</textarea></label>${r?'<label class="full">Correction reason<textarea name="reason" required></textarea></label>':''}</div><div class="form-actions"><button type="submit">Save report</button></div></form>`);const f=$('#entryForm');if(type==='Maintenance Timesheet')f.querySelectorAll('[data-maintenance-select]').forEach(select=>{const custom=f.querySelector(`[data-maintenance-custom="${select.dataset.maintenanceSelect}"]`);select.addEventListener('change',()=>{const other=select.value==='__other__';custom.hidden=!other;custom.required=other;if(other)custom.focus();});});if(type==='Water Meter'&&!r)setupWaterOpening(f);if(type==='Diesel Consumption'){const keys=['Opening Cans','Opening Barrels','Received Cans','Received Barrels','Issued Cans','Issued Barrels'];const preview=()=>{const litres=stage=>Number(f.elements.namedItem(stage+' Cans').value)*35+Number(f.elements.namedItem(stage+' Barrels').value)*200;const opening=litres('Opening'),received=litres('Received'),issued=litres('Issued');$('#dieselIssue').textContent='Opening: '+opening+' L | Received: '+received+' L | Issued: '+issued+' L | Closing: '+(opening+received-issued)+' L';};keys.forEach(k=>{const el=f.elements.namedItem(k);el.step='1';el.max='10000';el.addEventListener('input',preview);});preview();}if(type==='DG Operation'){const duration=f.elements.namedItem('Duration (HH:MM)');duration.placeholder='01:30';duration.pattern='[0-9]{1,2}:[0-5][0-9]';duration.inputMode='text';const preview=()=>{const match=duration.value.match(/^(\d{1,2}):([0-5]\d)$/);$('#dgConsumption').textContent=match?'Calculated diesel: '+((Number(match[1])*60+Number(match[2]))*26/60).toFixed(2)+' litres':'';};duration.addEventListener('input',preview);preview();}submit(f,async fd=>{const values={};fieldNames(type).concat('Remarks').forEach(k=>values[k]=fd.get(k));if(type==='Maintenance Timesheet')for(const k of ['Employee Name','Machine'])if(values[k]==='__other__')values[k]=fd.get(k+'__custom');await mutate(r?'correctReport':'saveReport',{id:r?.id,version:r?.version,type,date:fd.get('date'),shift:fd.get('shift'),fields:values,reason:fd.get('reason')});message(r?'Correction saved':'Report saved');});}
function setupWaterOpening(form){const meter=form.elements.namedItem('Meter Name'),date=form.elements.namedItem('date'),shift=form.elements.namedItem('shift'),opening=form.elements.namedItem('Opening Reading');let sequence=0,manual=false,autoValue='';opening.addEventListener('input',()=>{manual=true;});async function fetchOpening(){const request=++sequence,note=form.querySelector('#waterOpeningNote');if(!manual&&opening.value===autoValue)opening.value='';note.textContent='Looking up previous closing…';try{const result=await api('waterOpening',{meter:meter.value,date:date.value,shift:shift.value});if(request!==sequence||!form.isConnected)return;if(result.found){if(!manual){opening.value=result.reading;autoValue=result.reading;}note.textContent=(manual?'Previous closing (manual opening retained): ':'Opening fetched: ')+result.reading+' · '+result.date+' · '+result.shift+'. Verify before saving.';}else note.textContent=result.message||'No previous record for this meter. Enter opening manually.';}catch(err){if(request===sequence&&form.isConnected)note.textContent='Could not fetch opening: '+err.message+'. Enter verified opening manually.';}}[meter,date,shift].forEach(el=>el.addEventListener('change',fetchOpening));fetchOpening();}
async function openReport(id){try{const data=await api('reportDetail',{id}),r=data.report;modal(r.type+' · '+r.date,`<p>${esc(r.shift)} · ${badge(r.status)}</p>${r.source?`<p class="notice">Source: ${esc(r.source)}. Portal corrections are retained during sync; the original source Sheet is unchanged.</p>`:''}<dl class="details">${Object.entries({...r.fields,...derived(r)}).filter(([,v])=>v!=='').map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="form-actions">${reportPermission('correct',r.type)&&r.active!==false?'<button id="editReport" class="secondary">Correct entry</button>':''}${reportPermission('delete',r.type)&&r.active!==false?'<button id="deleteReport" class="danger">Delete from portal</button>':''}${admin()?`<button id="approveReport">${r.status==='Approved'?'Reopen for correction':'Approve & lock'}</button><button id="followTask" class="secondary">Assign follow-up task</button>`:''}</div><h2>Inquiry / remark</h2><form id="remarkForm"><label>Remark<textarea name="text" required maxlength="3000"></textarea></label>${admin()?`<div class="form-grid"><label>Responsible employee<select name="assignee" required>${employeeOptions('')}</select></label><label>Deadline IST<input name="due" type="datetime-local"></label></div><label class="check"><input name="createTask" type="checkbox" checked>Create a follow-up task for this remark</label>`:''}<div class="form-actions"><button type="submit">Save remark</button></div></form><h2>Review and correction history</h2>${data.activity.map(e=>`<div class="history"><b>${esc(e.action)}</b><small>${esc(e.by)} · ${esc(e.at)}</small><p>${esc(e.reason||e.text||'')}</p>${e.before&&e.after?Object.entries(e.after).filter(([k,v])=>e.before[k]!==v).map(([k,v])=>`<small>${esc(k)}: ${esc(e.before[k])} → ${esc(v)}</small>`).join('<br>'):''}</div>`).join('')||'<p class="muted">No history yet.</p>'}`);
 if($('#editReport'))$('#editReport').onclick=()=>portalCorrectionForm(r);if($('#deleteReport'))$('#deleteReport').onclick=async()=>{const reason=prompt('Delete this entry from portal reports and KPIs? Original Sheet and history are retained. Enter reason:');if(!reason?.trim())return;try{await mutate('removeReport',{id:r.id,version:r.version,reason});message('Entry deleted from portal. History retained.');}catch(e){message(e.message);}};
 if($('#followTask'))$('#followTask').onclick=()=>taskForm(null,r.id);if($('#approveReport'))$('#approveReport').onclick=async()=>{const mode=r.status==='Approved'?'reopen':'approve',reason=mode==='reopen'?prompt('Reason for reopening'):'';if(mode==='reopen'&&!reason)return;try{await mutate('reviewReport',{id:r.id,version:r.version,mode,reason});message(mode==='approve'?'Successfully Approved':'Report Reopened for Correction');}catch(e){message(e.message);}};
 const form=$('#remarkForm');if(form.elements.createTask)form.elements.createTask.onchange=()=>form.elements.due.required=form.elements.createTask.checked;if(form.elements.due)form.elements.due.required=true;
 submit(form,async fd=>{const due=fd.get('due');await mutate('remark',{id:r.id,text:fd.get('text'),assignee:fd.get('assignee'),createTask:fd.get('createTask')==='on',due:due?due+':00+05:30':''});message('Remark saved'+(fd.get('createTask')==='on'?' and task assigned':''));});
 }catch(e){message(e.message);}}
function taskForm(t,reportId=''){const choices=(state.users||[]).filter(u=>u.active&&(!taskManager()||u.email===t?.assignee||canManageDepartmentFront(u.department)));modal(t?'Edit task':'Assign / add task',`<form id="taskForm"><div class="form-grid"><label class="full">Task title<input name="title" maxlength="200" value="${esc(t?.title)}" required></label><label class="full">Instructions<textarea name="description">${esc(t?.description)}</textarea></label>${taskManager()?`<label class="full">Assign to employee(s)<select name="assignees" ${t?'':'multiple'} size="${t?'1':'6'}" required>${choices.map(u=>`<option value="${esc(u.email)}" ${(t?.assignee||taskEmployee)===u.email?'selected':''}>${esc(u.name)} · ${esc(u.department)}</option>`).join('')}</select><small>Choose several names for the same task. Each employee gets a separate completion checkbox.</small></label>`:`<p>Assigned to: ${esc(state.user.name)}</p>`}<label>Priority<select name="priority">${option(['High','Medium','Low'],t?.priority||'Medium')}</select></label><label>Deadline date IST<input name="due" type="date" required value="${esc(t?.due?.slice(0,10)||dateIST())}"></label></div><div class="form-actions"><button type="submit">Save task</button></div></form>`);submit($('#taskForm'),async fd=>{const due=fd.get('due'),assignees=fd.getAll('assignees');if(taskManager()&&!assignees.length)throw Error('Select at least one employee');if(taskManager()&&!t){const map=new Map(choices.map(u=>[u.email,u]));const groups=new Map();assignees.forEach(email=>{const person=map.get(email);if(!person)throw Error('Employee not found');if(!groups.has(person.department))groups.set(person.department,[]);groups.get(person.department).push(email);});const items=[...groups].map(([department,list])=>({title:fd.get('title'),description:fd.get('description'),priority:fd.get('priority'),date:due,department,assignees:list}));await mutate('bulkAssignTasks',{items});}else await mutate('saveTask',{id:t?.id,version:t?.version,title:fd.get('title'),description:fd.get('description'),assignee:taskManager()?assignees[0]:state.user.email,priority:fd.get('priority'),due:due+'T23:59:00+05:30',reportId:t?.reportId||reportId});message('Task saved');});}
let taskOpenRequest=0;
async function openTask(t,draft='',notice=''){if(!t)return message('Task is not accessible.');const request=++taskOpenRequest;try{modal('Loading task…','<p class="notice">Fetching the latest task.</p>');const fresh=await api('taskDetail',{id:t.id});if(request!==taskOpenRequest)return;if(!state)state={user:fresh.user,tasks:[],notifications:[],reports:[]};const index=state.tasks.findIndex(task=>task.id===t.id);if(index<0)state.tasks.push(fresh.task);else state.tasks[index]=fresh.task;t=fresh.task;if(!t)return message('Task is no longer accessible.');renderTaskDialog(t,draft,notice);}catch(error){message(error.message);}}
function renderTaskDialog(t,draft='',notice=''){const owner=admin(),canAct=owner||t.assignee===state.user.email;modal(t.title,`${notice?'<p class="notice">'+esc(notice)+'</p>':''}<p>${badge(t.status)} ${overdue(t)?'<span class="badge overdue">Overdue</span>':''}</p><p>${esc(t.description)}</p><p>Assigned: ${esc(t.assignee)}<br>Deadline IST: ${esc(t.due)}</p>${t.workUpdate?'<div class="history"><b>Employee work update</b><p>'+esc(t.workUpdate)+'</p></div>':''}${t.reviewRemark?'<div class="history"><b>Review remark</b><p>'+esc(t.reviewRemark)+'</p></div>':''}${t.pendingReason?'<div class="history"><b>Pending reason</b><p>'+esc(t.pendingReason)+'</p></div>':''}${t.removalRequest?'<div class="history"><b>Removal request: '+esc(t.removalRequest.status)+'</b><p>'+esc(t.removalRequest.reason)+'</p><p>'+esc(t.removalRequest.remark||'')+'</p></div>':''}<form id="taskAction"><label>Work update / review remark<textarea name="text">${esc(draft)}</textarea></label><div class="form-actions"><button type="button" id="reloadTask" class="secondary">Reload latest task</button>${canAct&&['Pending','In progress'].includes(t.status)?'<button type="submit" name="mode" value="submit">✓ Completed</button><button type="submit" name="mode" value="pending" class="secondary">Pending — reason required</button>':''}${canAct&&!owner&&!['Closed','Removed'].includes(t.status)&&t.removalRequest?.status!=='Requested'?'<button type="submit" name="mode" value="requestRemoval" class="secondary">Request task removal</button>':''}${owner&&t.removalRequest?.status==='Requested'?'<button type="submit" name="mode" value="approveRemoval" class="danger">Approve removal</button><button type="submit" name="mode" value="rejectRemoval" class="secondary">Reject removal</button>':''}${owner&&t.status==='Submitted'?'<button type="submit" name="mode" value="close">Approve & close</button>':''}${owner&&['Submitted','Closed'].includes(t.status)?'<button type="submit" name="mode" value="return" class="danger">Return for correction</button>':''}${owner&&['Pending','In progress'].includes(t.status)?'<button type="button" id="editTask" class="secondary">Edit assignment / deadline</button>':''}</div></form>`);$('#taskAction').onsubmit=async e=>{e.preventDefault();const button=e.submitter;if(!button)return;const form=e.target,text=String(new FormData(form).get('text')||'').trim();if(['return','submit','pending','requestRemoval','approveRemoval','rejectRemoval'].includes(button.value)&&!text){message(button.value==='return'?'Write the correction remark before returning the task.':'Write the work update, pending reason or removal decision remark.');form.elements.text.focus();return;}const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await mutate('taskAction',{id:t.id,version:t.version,mode:button.value,text});message(button.value==='return'?'Successfully Returned':button.value==='close'?'Successfully Approved':button.value==='submit'?'Completed — awaiting review':button.value==='requestRemoval'?'Removal request sent for approval':button.value==='approveRemoval'?'Task removal approved':button.value==='rejectRemoval'?'Task removal rejected':'Task updated');}catch(err){if(/Record changed/.test(err.message)){await openTask(t,text,'This task changed while you were reviewing. Latest data is loaded and your draft remark is preserved. Review the update and choose the action again.');}else message(err.message);}finally{buttons.forEach(b=>b.disabled=false);}};$('#reloadTask').onclick=()=>openTask(t,String(new FormData($('#taskAction')).get('text')||''));if($('#editTask'))$('#editTask').onclick=()=>taskForm(t);}
function permissionChecks(name,selected,options){return options.map(t=>'<label class="check"><input type="checkbox" name="'+name+'" value="'+esc(t)+'" '+(selected.includes(t)?'checked':'')+'>'+esc(t)+'</label>').join('');}
