async function ensurePdf(){for(const [src,key] of [['pdf-lib.min.js','PDFLib'],['fontkit.umd.min.js','fontkit']]){if(globalThis[key])continue;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='./'+src;script.onload=resolve;script.onerror=()=>reject(Error('Upload missing PDF file: '+src));document.head.append(script);});}}
$('#pinForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const r=await api('loginPin',{phone:$('#phone').value,pin:$('#pin').value});token=r.token;sessionStorage.setItem('starish-session',token);$('#pin').value='';await load();}catch(error){message(error.message);}finally{button.disabled=false;}};
