function matchingEmployees(employees,query){const words=String(query||'').trim().toLowerCase().split(/\s+/).filter(Boolean);return employees.filter(e=>{const text=[e.name,e.department,e.email,e.phone].filter(Boolean).join(' ').toLowerCase();return words.every(word=>text.includes(word));});}

function taskKind(t){return t.routineId||t.createdBy==='scheduler'?'daily':t.createdBy===t.assignee?'additional':'assigned';}
function canManageDepartmentFront(dept){return admin()||(state?.user?.managedDepartments||[]).includes('*')||(state?.user?.managedDepartments||[]).includes(dept);}
function taskDueDay(t){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(t.due));}
function taskTypeLabel(t){return taskKind(t)==='daily'?'Preplanned daily':taskKind(t)==='assigned'?'New assignment':'Additional task';}
function tasksHtml(){

 if(!allTaskViewer()){
  const all=scopedTasks(),today=all.filter(t=>t.status!=='Removed'&&taskDueDay(t)===dateIST()),completed=today.filter(t=>['Submitted','Closed'].includes(t.status)).length,pending=today.length-completed,efficiency=today.length?Math.round(completed/today.length*100):0;
  const tasks=all.filter(t=>t.status!=='Removed'&&taskDueDay(t)===dateIST()).filter(t=>taskView==='pending'?!['Submitted','Closed'].includes(t.status):taskView==='completed'?['Submitted','Closed'].includes(t.status):taskView==='overdue'?overdue(t):['assigned','daily','additional'].includes(taskView)?taskKind(t)===taskView:true).filter(t=>JSON.stringify(t).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>({daily:0,assigned:1,additional:2}[taskKind(a)]-{daily:0,assigned:1,additional:2}[taskKind(b)])||a.due.localeCompare(b.due));
  const views=['all','pending','completed','assigned','daily','additional','overdue'],labels={all:'All tasks',pending:'Pending tasks',completed:'Completed tasks',assigned:'New assignments',daily:'Daily preplanned',additional:'My additional tasks',overdue:'Overdue tasks'},managerControls=taskManager()?'<div class="toolbar"><button data-new-task>+ Assign task</button></div>':'<div class="toolbar"><button data-new-task>+ Add my additional task</button><small>This task will be added only to your own list.</small></div>';
  return managerControls+'<section class="my-task-list"><h2 class="task-day-heading">Today&#39;s task dashboard <small>'+esc(dateIST())+' · India time</small></h2><div class="task-counts task-daily-kpis"><div><small>Today total</small><strong>'+today.length+'</strong></div><div><small>Completed</small><strong>'+completed+'</strong></div><div><small>Pending</small><strong>'+pending+'</strong></div><div><small>Work efficiency</small><strong>'+efficiency+'%</strong></div></div><p class="muted task-efficiency-note">Efficiency = completed tasks ÷ today&#39;s assigned tasks.</p><div class="toolbar"><select id="taskView">'+views.map(v=>'<option value="'+v+'" '+(v===taskView?'selected':'')+'>'+labels[v]+'</option>').join('')+'</select><input id="taskSearch" placeholder="Search tasks" value="'+esc(search)+'"></div><div class="card table-wrap excel-report task-list-table"><table><thead><tr><th>Done</th><th>Task</th><th>Type</th><th>Due date &amp; time</th><th>Status</th></tr></thead><tbody>'+(tasks.map(t=>{const done=['Submitted','Closed'].includes(t.status),disabled=t.status==='Closed'||t.removalRequest?.status==='Requested';return '<tr class="'+(done?'task-row-complete':'')+'"><td><label class="task-table-check"><input type="checkbox" data-task-check="'+esc(t.id)+'" aria-label="Mark '+esc(t.title)+' '+(done?'pending':'complete')+'" '+(done?'checked ':'')+(disabled?'disabled':'')+'><span>'+(done?'Done':'To do')+'</span></label></td><td><b>'+esc(t.title)+'</b>'+(t.description?'<small>'+esc(t.description)+'</small>':'')+(t.pendingReason?'<small>Pending reason: '+esc(t.pendingReason)+'</small>':'')+'</td><td>'+esc(taskTypeLabel(t))+'</td><td>'+esc(new Date(t.due).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))+(overdue(t)&&!done?'<small class="badge overdue">Overdue</small>':'')+'</td><td>'+(done?'<span class="badge approved">Complete</span>':badge(t.status))+'</td></tr>';}).join('')||'<tr><td colspan="5" class="empty">No tasks in this list.</td></tr>')+'</tbody></table></div><p class="muted">Daily preplanned tasks appear first. New assignments appear underneath. Tick a checkbox when a task is complete; untick it to return the task to pending.</p></section>';
 }
const views=['all','pending','completed','assigned','daily','additional','overdue'].concat(taskManager()?['removal','removed']:[]),labels={all:'All tasks',pending:'Pending tasks',completed:'Completed tasks',assigned:'Assigned tasks',daily:'Daily tasks',additional:'My additional tasks',overdue:'Overdue tasks',removal:'Removal approval requests',removed:'Removed tasks (history)'};const tasks=scopedTasks().filter(t=>taskView==='removed'?t.status==='Removed':t.status!=='Removed').filter(t=>taskView==='pending'?!['Submitted','Closed'].includes(t.status):taskView==='completed'?['Submitted','Closed'].includes(t.status):taskView==='overdue'?overdue(t):taskView==='removal'?t.removalRequest?.status==='Requested':['assigned','daily','additional'].includes(taskView)?taskKind(t)===taskView:true).filter(t=>JSON.stringify(t).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>a.due.localeCompare(b.due));return `${taskManager()?taskEmployeePicker():''}<div class="toolbar"><button data-new-task>+ ${taskManager()?'Assign task':'Add my additional task'}</button><select id="taskView">${views.map(v=>`<option value="${v}" ${taskView===v?'selected':''}>${labels[v]}</option>`).join('')}</select><input id="taskSearch" placeholder="Search tasks" value="${esc(search)}"><small>Completed work awaits management review. Removal needs approval.</small></div>${['daily','assigned','additional'].map(kind=>{const list=tasks.filter(t=>taskKind(t)===kind);if(!list.length)return '';return `<h2>${kind==='daily'?'Daily task list':kind==='assigned'?'Assigned tasks':'Additional tasks'}</h2><div class="card table-wrap"><table><thead><tr><th>Task / reason</th><th>Employee</th><th>Deadline IST</th><th>Status</th><th>Action</th></tr></thead><tbody>${list.map(t=>`<tr><td><b>${esc(t.title)}</b><small>${esc(t.description)}</small>${t.pendingReason?'<small>Pending: '+esc(t.pendingReason)+'</small>':''}${t.removalRequest?'<small>Removal '+esc(t.removalRequest.status)+': '+esc(t.removalRequest.reason)+'</small>':''}${t.reviewRemark?'<small>Review: '+esc(t.reviewRemark)+'</small>':''}</td><td>${esc((state.users||[]).find(u=>u.email===t.assignee)?.name||t.assignee)}</td><td>${esc(new Date(t.due).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</td><td>${overdue(t)?'<span class="badge overdue">OVERDUE</span> ':''}${['Submitted','Closed'].includes(t.status)?'<span class="badge approved">✓ Completed'+(t.status==='Submitted'?' · Awaiting review':' · Approved')+'</span>':badge(t.status)}</td><td><button data-task="${esc(t.id)}">Open</button>${t.assignee===state.user.email&&['Pending','In progress'].includes(t.status)?`<button data-task-id="${esc(t.id)}" data-task-mode="submit">Completed</button><button class="secondary" data-task-id="${esc(t.id)}" data-task-mode="pending">Pending</button>`:''}${t.assignee===state.user.email&&!['Closed','Removed'].includes(t.status)&&t.removalRequest?.status!=='Requested'?`<button class="secondary" data-task-id="${esc(t.id)}" data-task-mode="requestRemoval">Request removal</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}).join('')}${!tasks.length?'<div class="card empty">No tasks in this view. Daily routines must be enabled and assigned by management.</div>':''}`;}
async function setTaskCheckbox(id,completed,input){const t=state.tasks.find(x=>x.id===id);if(!t)return;input.disabled=true;try{await mutate('taskAction',{id:t.id,version:t.version,mode:'checkbox',completed});message(completed?'Task marked complete':'Task marked pending');}catch(e){input.checked=!completed;input.disabled=false;message(e.message);if(/Record changed/.test(e.message))await load();}}
async function quickTaskAction(id,mode,button){const t=state.tasks.find(t=>t.id===id);if(!t)return;const text=prompt(mode==='submit'?'Completed work update:':mode==='pending'?'Why is this task pending?':'Why should this task be removed?');if(text===null)return;if(!text.trim())return message('Reason / work update is required.');button.disabled=true;try{await mutate('taskAction',{id:t.id,version:t.version,mode,text:text.trim()});message(mode==='submit'?'Completed — awaiting review':mode==='pending'?'Pending reason saved':'Removal request sent for approval');}catch(e){message(e.message);if(/Record changed/.test(e.message))await load();}finally{button.disabled=false;}}

function allTaskViewer(){return admin()||state?.user?.taskScope==='all';}
function scopedTasks(){return state.tasks.filter(t=>!allTaskViewer()||!taskEmployee||t.assignee===taskEmployee);}
function taskEmployeeChoices(){const choices=new Map((state.users||[]).map(u=>[u.email,{id:u.email,name:u.name||u.email}]));state.tasks.forEach(t=>{if(!choices.has(t.assignee))choices.set(t.assignee,{id:t.assignee,name:t.assignee});});return [...choices.values()].sort((a,b)=>a.name.localeCompare(b.name));}
function taskEmployeePicker(){const choices=taskEmployeeChoices().filter(u=>u.id===taskEmployee||u.name.toLowerCase().includes(taskEmployeeSearch.toLowerCase()));return `<div class="card"><h2>Employee task overview</h2><div class="toolbar"><label>Search employee name<input id="taskEmployeeSearch" type="text" value="${esc(taskEmployeeSearch)}" placeholder="Type employee name"></label><label>Employee<select id="taskEmployee"><option value="">All employees</option>${choices.map(u=>`<option value="${esc(u.id)}" ${u.id===taskEmployee?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label></div><small>Task counts and tap views use the selected employee. Report date filters apply to reports.</small></div>`;}
function employeeTaskOverview(){const tasks=scopedTasks().filter(t=>t.status!=='Removed').filter(t=>taskView==='pending'?!['Submitted','Closed'].includes(t.status):taskView==='completed'?['Submitted','Closed'].includes(t.status):taskView==='assigned'?taskKind(t)==='assigned':taskView==='overdue'?overdue(t):taskView==='removal'?t.removalRequest?.status==='Requested':true),ids=taskEmployee?[taskEmployee]:[...new Set(tasks.map(t=>t.assignee))],names=new Map(taskEmployeeChoices().map(u=>[u.id,u.name]));names.set(state.user.email,state.user.name);function section(title,list){return `<div class="card table-wrap"><h3>${title}</h3><table><thead><tr><th>Task</th><th>Status</th></tr></thead><tbody>${list.map(t=>`<tr><td><button class="secondary" data-task="${esc(t.id)}">${esc(t.title)}</button><small>Deadline: ${esc(new Date(t.due).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}</small>${t.pendingReason?'<small>Reason: '+esc(t.pendingReason)+'</small>':''}${t.removalRequest?.status==='Requested'?'<small>Removal approval requested</small>':''}</td><td>${['Submitted','Closed'].includes(t.status)?'<span class="badge approved">✓ Completed</span><small>'+(t.status==='Submitted'?'Awaiting review':'Approved')+'</small>':'<span class="badge">Pending</span>'}${overdue(t)?'<small class="badge overdue">Overdue</small>':''}</td></tr>`).join('')||'<tr><td colspan="2">No tasks</td></tr>'}</tbody></table></div>`;}return `<div class="toolbar"><h2>Employee tasks · ${esc(taskView==='all'?'All':taskView)}</h2><button class="secondary" data-task-view="all">${admin()?'Close task view':'Show all tasks'}</button></div>${ids.map(id=>{const own=tasks.filter(t=>t.assignee===id),daily=own.filter(t=>taskKind(t)==='daily'),assigned=own.filter(t=>taskKind(t)==='assigned'),extra=own.filter(t=>taskKind(t)==='additional');return `<section><h2>${esc(names.get(id)||id)}</h2><div class="grid">${section('Daily tasks',daily)}${section('Assigned tasks',assigned)}${extra.length?section('Additional tasks',extra):''}</div></section>`;}).join('')||'<div class="card empty">No tasks assigned yet. Assign and enable Daily routines to generate daily tasks.</div>'}`;}

function departmentManagementHtml(){const names=[...new Set([...(state.departments||[]).map(d=>d.name),...(state.employees||[]).map(e=>e.department).filter(Boolean)])].sort((a,b)=>a.localeCompare(b));return `<div class="toolbar">${canCreateDepartment()?'<button id="newDepartment">+ Create department</button>':''}${taskManager()?'<button data-new-employee>+ Add employee</button>':''}<button id="downloadTaskTemplate" class="secondary">Download Excel template</button><button id="uploadTaskList" class="secondary">Upload Excel task list</button><small>Department managers can manage only the departments assigned by you.</small></div><div class="grid">${names.map(name=>{const people=state.employees.filter(e=>e.active!==false&&e.department===name),sop=(state.departmentSops||[]).find(x=>x.department===name);return `<div class="summary-card"><button class="link-button" data-dept-people="${esc(name)}"><small>DEPARTMENT</small><h2>${esc(name)}</h2><div class="metric"><span>Employees · tap to view names</span><b>${people.length}</b></div><span class="link">${sop?'SOP available':'SOP not added'}</span></button><div class="form-actions"><button class="secondary" data-assign-department="${esc(name)}">Assign employees</button></div></div>`;}).join('')||'<div class="card empty">No departments configured yet.</div>'}</div><div class="card"><h2>Department SOP</h2><div class="form-actions">${names.map(name=>`<button class="secondary" data-edit-sop="${esc(name)}">${esc((state.departmentSops||[]).some(x=>x.department===name)?'Edit · ':'Add SOP · ')}${esc(name)}</button>`).join('')}</div><p class="muted">Employees see the SOP for their assigned department in Department SOP.</p></div>`;}
function departmentSopHtml(){const own=(state.departmentSops||[]).filter(x=>x.department===state.user.department);return own.map(x=>`<article class="card"><h2>${esc(x.title||x.department+' SOP')}</h2><p class="muted">${esc(x.department)} · Updated ${esc(String(x.updatedAt||'').slice(0,10))}</p><div class="sop-content">${esc(x.content).replace(/\n/g,'<br>')}</div></article>`).join('')||'<div class="card empty">Your department SOP has not been added yet. Please contact your department manager.</div>';}
function assignEmployeesForm(department){const list=state.employees.filter(e=>e.active!==false&&e.department!==department);modal('Assign employees · '+department,'<form id="assignEmployeesForm"><label>Search employee<input id="employeeAssignSearch" type="search" placeholder="Search name, department, email or mobile"></label><label>Choose employee(s)<select id="employeeAssignList" name="employeeIds" multiple size="10" required></select></label><small>Choose from employees available to your department management access. Moving an employee requires access to their current department.</small><div class="form-actions"><button type="submit">Assign to department</button></div></form>');const search=$('#employeeAssignSearch'),select=$('#employeeAssignList');const selectedIds=new Set();select.onchange=()=>{Array.from(select.options).forEach(o=>o.selected?selectedIds.add(o.value):selectedIds.delete(o.value));};const refresh=()=>{const query=search.value.trim().toLowerCase(),filtered=list.filter(e=>[e.name,e.department,e.email,e.phone].some(v=>String(v||'').toLowerCase().includes(query)));select.innerHTML=filtered.map(e=>'<option value="'+esc(e.id)+'" '+(selectedIds.has(e.id)?'selected':'')+'>'+esc(e.name)+' · '+esc(e.department||'No department')+'</option>').join('');};refresh();search.oninput=refresh;submit($('#assignEmployeesForm'),async fd=>{await mutate('assignEmployeesToDepartment',{department,employeeIds:fd.getAll('employeeIds')});message('Employees assigned to '+department);});}
let taskReportRows=[],taskReportView='date';
function taskReportHtml(){return `<div class="toolbar"><label>From<input id="taskReportFrom" type="date" value="${esc($('#from').value)}"></label><label>To<input id="taskReportTo" type="date" value="${esc($('#to').value)}"></label><label>Employee name<input id="taskReportEmployeeSearch" type="search" placeholder="Search employee" value="${esc(taskReportEmployeeSearch)}"></label><button id="generateTaskReport">Show report</button><button id="downloadTaskReportPdf" class="secondary">Download PDF</button></div><p class="notice">Search by employee name to narrow the selected date range. A task stays pending if it was not reported complete on its work date. Past day employee checkboxes lock automatically.</p><div id="taskReportResults">${taskReportTable(taskReportRows)}</div>`;}
function taskReportDisplayRows(rows){if(taskReportView==='date')return rows;const range=$('#taskReportFrom')&&$('#taskReportTo')?$('#taskReportFrom').value+' – '+$('#taskReportTo').value:'Selected range',groups=new Map();rows.forEach(r=>{const g=groups.get(r.employee)||{date:range,employee:r.employee,total:0,complete:0,pending:0,tasks:[]};g.total+=r.total;g.complete+=r.complete;g.pending+=r.pending;g.tasks.push(...r.tasks);groups.set(r.employee,g);});return [...groups.values()].map(g=>({...g,efficiency:g.total?Math.round(g.complete/g.total*100):0})).sort((x,y)=>x.employee.localeCompare(y.employee));}
function bindTaskReportTable(){document.querySelectorAll('[data-task-report-view]').forEach(b=>b.onclick=()=>{taskReportView=b.dataset.taskReportView;$('#taskReportResults').innerHTML=taskReportTable(taskReportRows);bindTaskReportTable();});document.querySelectorAll('[data-task-report-row]').forEach(x=>x.onclick=()=>taskReportDetail(taskReportDisplayRows(taskReportRows.filter(r=>!taskReportEmployeeSearch.trim()||String(r.employee||'').toLowerCase().includes(taskReportEmployeeSearch.trim().toLowerCase())))[Number(x.dataset.taskReportRow)]));const employeeSearch=$('#taskReportEmployeeSearch');if(employeeSearch)employeeSearch.oninput=()=>{taskReportEmployeeSearch=employeeSearch.value;$('#taskReportResults').innerHTML=taskReportTable(taskReportRows);bindTaskReportTable();const active=$('#taskReportEmployeeSearch');active.focus();active.setSelectionRange(active.value.length,active.value.length);};const pdf=$('#downloadTaskReportPdf');if(pdf)pdf.onclick=exportTaskReportPdf;}
function taskReportTable(rows){const q=taskReportEmployeeSearch.trim().toLocaleLowerCase(),filtered=rows.filter(r=>!q||String(r.employee||'').toLocaleLowerCase().includes(q)),display=taskReportDisplayRows(filtered);if(!rows.length)return '<div class="toolbar"><button data-task-report-view="date" '+(taskReportView==='date'?'class="active"':'')+'>Date-wise</button><button data-task-report-view="employee" '+(taskReportView==='employee'?'class="active"':'')+'>Employee-wise</button></div><div class="card empty">Select a date range and show the report.</div>';if(!filtered.length)return '<div class="toolbar"><button data-task-report-view="date" '+(taskReportView==='date'?'class="active"':'')+'>Date-wise</button><button data-task-report-view="employee" '+(taskReportView==='employee'?'class="active"':'')+'>Employee-wise</button></div><div class="card empty">No employee or tasks match this search.</div>';const total=filtered.reduce((a,r)=>a+r.total,0),done=filtered.reduce((a,r)=>a+r.complete,0),pending=filtered.reduce((a,r)=>a+r.pending,0);return '<div class="toolbar"><button data-task-report-view="date" '+(taskReportView==='date'?'class="active"':'')+'>Date-wise</button><button data-task-report-view="employee" '+(taskReportView==='employee'?'class="active"':'')+'>Employee-wise</button><small>'+ (taskReportView==='employee'?'Employee totals for the selected date range':'Daily employee-wise details')+' · '+filtered.length+' report rows</small></div><div class="kpis"><div class="card"><small>Tasks</small><strong>'+total+'</strong></div><div class="card"><small>Complete</small><strong>'+done+'</strong></div><div class="card"><small>Pending</small><strong>'+pending+'</strong></div><div class="card"><small>Efficiency</small><strong>'+(total?Math.round(done/total*100):0)+'%</strong></div></div><div class="card table-wrap"><table><thead><tr><th>'+ (taskReportView==='employee'?'Date range':'Date')+'</th><th>Employee</th><th>Total</th><th>Complete</th><th>Pending</th><th>Eff%</th><th>Details</th></tr></thead><tbody>'+display.map((r,i)=>'<tr><td>'+esc(r.date)+'</td><td>'+esc(r.employee)+'</td><td>'+r.total+'</td><td>'+r.complete+'</td><td>'+r.pending+'</td><td>'+r.efficiency+'%</td><td><button data-task-report-row="'+i+'">Tap to view</button></td></tr>').join('')+'</tbody></table></div>';}
