function removeDepartmentEmployeeDialog(employee){if(!employee)return;modal('Remove from department', '<p>Remove <b>'+esc(employee.name)+'</b> from '+esc(employee.department)+'?</p><p class="notice">Their portal account, tasks, and history will remain. Only the department assignment will be cleared.</p><div class="form-actions"><button type="button" class="danger" id="confirmDepartmentRemoval">Remove from department</button><button type="button" class="secondary" onclick="document.querySelector(\'#dialog\').close()">Cancel</button></div>');$('#confirmDepartmentRemoval').onclick=async e=>{e.target.disabled=true;try{await mutate('removeEmployeeFromDepartment',{id:employee.id,version:employee.version});message(employee.name+' removed from '+employee.department);}catch(err){message(err.message);e.target.disabled=false;}};}
