async function managementRemove(action,record){const reason=prompt(action==='removeEmployee'?'Remove employee access and stop future routine assignments. Reason:':'Remove task from active list. Reason:');if(reason===null)return;if(!reason.trim())return message('Reason required');try{await mutate(action,{id:record.id,version:record.version,reason});message('Removed. History retained.');}catch(e){message(e.message);}}

function reportKpis(){
 if(reportType==='Boiler'){const table=buildReportTable('Boiler',filtered(),{mode:'cumulative'});return table.rows.filter(r=>['Total Water Consumption','Total Fuel Consumption','Total Steam Consumption','Wood Received Qty'].includes(r.values.Parameter)).map(r=>({label:r.values.Parameter,value:r.values.Actual}));}
 const table=buildReportTable(reportType,filtered(),{mode:'daily',changeover:state.batchChangeover});
 if(reportType.includes('Production')&&table.totals){const keys=reportType==='Boardline Production'?['Tonnage (kg)','Meter','Speed/Min','Breakdown','Running Hrs','Eff %']:['Number of Jobs','Actual Quantity','Speed/Min','Breakdown','Running Hrs'];return keys.map(label=>({label,value:table.totals[label]}));}
 return summary(reportType,filtered(),state.batchChangeover);
}
function reportKpisHtml(){return `<details class="card report-kpi-panel"><summary><b>Report KPIs</b> · Tap to show / hide</summary><div class="kpis" style="margin-top:16px">${reportKpis().map((m,i)=>`<button class="card" data-report-kpi="${i}"><small>${esc(m.label)}</small><strong>${esc(m.value)}</strong><small>Tap for details</small></button>`).join('')}</div></details>`;}
function openKpiDetails(index){const metric=reportKpis()[index];if(!metric)return;const table=buildReportTable(reportType,filtered(),{mode:'daily',changeover:state.batchChangeover,visibleColumns:state.reportColumns?.[reportType]});const formulas={'Running Hrs':'Elapsed hours minus breakdown minutes / 60. Overlapping Boardline records require verification.','Speed/Min':'Total output / (total running hours × 60).','Eff %':'Total metres / (total running hours × 4000) × 100.','Glue (kg/ton)':'Matched starch issued kg / matched Day + Night Boardline tonnes.','Batch equivalents':'Starch kg / batch size: 200 kg before 10-Sep-2026, 150 kg thereafter.'};modal(metric.label,`<p><strong>${esc(metric.value)}</strong></p><p>${esc(reportType)} · ${esc($('#from').value)} to ${esc($('#to').value)}</p><p>${esc(formulas[metric.label]||'Calculated from the report records in the selected date range.')}</p><div class="table-wrap"><table><thead><tr>${table.columns.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(row=>`<tr>${table.columns.map(k=>`<td>${esc(row.values[k]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);}

function analysisData(){
 const categoryField=reportType==='Water Meter'?'Meter Name':reportType==='Glue Kitchen Stock'?'Material Name':reportType.includes('Production')&&reportType!=='Boardline Production'?'Machine / Process':reportType.includes('Timesheet')?'Employee Name':'';
 const entries=reportType==='Glue Consumption'?state.reports:filtered();
 const metrics=analysisMetrics(reportType,entries,state.batchChangeover),visible=state.reportColumns?.[reportType];
 const available=visible?.length?metrics.filter(m=>visible.includes(m)||['Records','Valid days'].includes(m)):metrics;
 if(!available.includes(analysisMetric))analysisMetric=available[0]||'Records';
 const categories=categoryField?[...new Set(entries.filter(r=>r.type===reportType).map(r=>r.fields[categoryField]).filter(Boolean))].sort():[];
 if(!categories.includes(analysisCategory))analysisCategory=reportType==='Water Meter'?(categories.includes('MAIN')?'MAIN':categories[0]||''):'';
 const options={from:$('#from').value,to:$('#to').value,metric:analysisMetric,changeover:state.batchChangeover,categoryField,category:analysisCategory};
 const rows=analysisPeriod==='Date'?dateAnalysis(reportType,entries,options):monthlyAnalysis(reportType,entries,options);
 return {categoryField,categories,metrics:available,rows,period:analysisPeriod};
}
function analysisHtml(){
 const available=visibleTypes();if(!available.includes(reportType))reportType=available[0]||'';
 const d=analysisData(),dateMode=d.period==='Date';
 return `<div class="toolbar"><label>Period<select id="analysisPeriod">${option(['Month','Date'],analysisPeriod)}</select></label><label>Metric<select id="analysisMetric">${option(d.metrics,analysisMetric)}</select></label>${d.categories.length?`<label>${esc(d.categoryField)}<select id="analysisCategory">${reportType==='Water Meter'?'':'<option value="">All</option>'}${option(d.categories,analysisCategory)}</select></label>`:''}<label>Graph<select id="analysisChart">${option(['bar','line'],analysisChart)}</select></label><button id="analysisDownload" class="secondary">Download analysis CSV</button></div><div class="card"><h2>${esc(reportType)} · ${esc(analysisMetric)}</h2><p class="muted">${esc(metricMethod(reportType,analysisMetric,d.period))}. Missing values appear as gaps; zero remains zero.</p>${analysisSvg(d.rows,d.period)}<p class="muted">${dateMode?'Date-wise view shows every date in the selected range; dates without matching reports remain blank.':'Partial month means the selected dates cover only part of that month. Available days do not prove full month data.'}</p></div><div class="card table-wrap excel-report" style="margin-top:16px"><table><thead><tr><th>${d.period}</th><th>${esc(analysisMetric)}</th><th>Report rows</th><th>Available / matched days</th>${dateMode?'':'<th>Range</th>'}</tr></thead><tbody>${d.rows.map(r=>`<tr><td>${esc(dateMode?r.date:r.month)}</td><td>${r.value===null?'Unavailable':esc(r.value.toLocaleString('en-IN',{maximumFractionDigits:2}))}</td><td>${r.records}</td><td>${r.validDays}</td>${dateMode?'':`<td>${r.partial?'Partial month':'Full month selected'}</td>`}</tr>`).join('')}</tbody></table></div>`;
}
function analysisSvg(rows,period='Month'){
 const valid=rows.filter(r=>r.value!==null);if(!valid.length)return '<div class="empty">No valid values. Select a wider date range or sync source reports.</div>';
 const dateMode=period==='Date',step=dateMode?(rows.length>45?18:72):90,w=Math.max(680,rows.length*step),h=330,left=75,right=25,top=35,bottom=65,plot=h-top-bottom;
 const min=Math.min(0,...valid.map(r=>r.value)),max=Math.max(0,...valid.map(r=>r.value))||1,span=max-min||1,y=v=>top+(max-v)/span*plot,x=i=>left+step*(i+.5);
 const labelEvery=dateMode?Math.max(1,Math.ceil(rows.length/35)):1;
 let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(reportType+' '+(dateMode?'date-wise':'month-wise')+' '+analysisMetric)}"><rect width="100%" height="100%" fill="white"/>`;
 for(let i=0;i<=4;i++){const v=min+span*i/4;svg+=`<line x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}" stroke="#dce5ec"/><text x="${left-8}" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#647789">${esc(v.toLocaleString('en-IN',{maximumFractionDigits:1}))}</text>`;}
 let prior=null;rows.forEach((r,i)=>{
  const label=dateMode?r.date.slice(8,10)+'/'+r.date.slice(5,7):r.month;
  if(i%labelEvery===0||i===rows.length-1)svg+=`<text x="${x(i)}" y="${h-30}" text-anchor="middle" font-size="${dateMode?'10':'12'}" fill="#14334b">${esc(label)}</text>`;
  if(r.value===null){prior=null;return;}const xx=x(i),yy=y(r.value);
  if(analysisChart==='line'){if(prior)svg+=`<line x1="${prior.x}" y1="${prior.y}" x2="${xx}" y2="${yy}" stroke="#009b7d" stroke-width="3"/>`;svg+=`<circle cx="${xx}" cy="${yy}" r="5" fill="#009b7d"><title>${esc(label+': '+r.value)}</title></circle>`;prior={x:xx,y:yy};}
  else svg+=`<rect x="${xx-step*.28}" y="${Math.min(yy,y(0))}" width="${step*.56}" height="${Math.max(1,Math.abs(yy-y(0)))}" fill="#009b7d" rx="3"><title>${esc(label+': '+r.value)}</title></rect>`;
  if(!dateMode||rows.length<=35)svg+=`<text x="${xx}" y="${yy-9}" text-anchor="middle" font-size="11" fill="#14334b">${esc(r.value.toLocaleString('en-IN',{maximumFractionDigits:2}))}</text>`;
 });
 return '<div style="overflow-x:auto;max-width:100%">'+svg+'</svg></div>';
}
function downloadAnalysisCsv(){
 const d=analysisData(),cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
 const header=d.period==='Date'?[d.period,analysisMetric,'Report rows','Available / matched days']:[d.period,analysisMetric,'Report rows','Available days','Partial month'];
 const lines=[header,...d.rows.map(r=>d.period==='Date'?[r.date,r.value??'',r.records,r.validDays]:[r.month,r.value??'',r.records,r.validDays,r.partial?'Yes':'No'])];
 const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));
 const a=document.createElement('a');a.href=url;a.download='Starish_Analysis_'+reportType.replace(/\s/g,'_')+'_'+(d.period==='Date'?'Date':'Month')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);
}

let boilerEntryType='Boiler',boilerEntryDrafts={};
const boilerEntryTypes=['Boiler','Boiler Hourly Log','Boiler Water Tests'];

function boilerEntryHtml(){if(!reportPermission('entry','Boiler'))return '<p>No Boiler entry permission.</p>';return `<div class="toolbar"><button id="boilerExcelUpload">Upload Boiler Summary Excel</button></div><div class="card"><h2>Daily Boiler Summary</h2><p>One summary per date. Leave unavailable values blank. Enter daily averages and approved standards.</p><form id="boilerEntryForm"><label>Date<input name="date" type="date" value="${dateIST()}" required></label><label>Operator<input name="Operator" value="${esc(state.user.name)}"></label><div class="table-wrap"><table><thead><tr><th>Parameter</th><th>Standard</th><th>Actual</th><th>Remarks</th></tr></thead><tbody>${METRICS.map(([label,key,std,method])=>`<tr><td>${esc(label)}</td><td><input name="${esc('Standard: '+key)}" value="${esc(std)}"></td><td><input name="${esc(key)}" type="${method==='text'?'text':'number'}" ${method==='text'?'':'min="0" step="any"'}></td><td><input name="${esc('Remark: '+key)}"></td></tr>`).join('')}</tbody></table></div><h3>Day/Night consumption (optional)</h3><div class="form-grid">${SHIFT_FIELDS.map(k=>`<label>${esc(k)}<input name="${esc(k)}" type="number" min="0" step="any"></label>`).join('')}</div><label>General remarks<textarea name="Remarks"></textarea></label><button type="submit">Save daily summary to Google Sheet</button><p data-save-status></p></form></div>`;}

function bindBoilerEntry(){if($('#boilerExcelUpload'))$('#boilerExcelUpload').onclick=boilerExcelForm;const form=$('#boilerEntryForm');if(form)submit(form,async fd=>{const fields={'Summary Format':'daily-v1','Time Slot':'Daily'};for(const [k,v] of fd.entries())if(k!=='date')fields[k]=v;await mutate('saveReport',{type:'Boiler',date:fd.get('date'),shift:'Daily',fields});message('Daily Boiler Summary saved');});}

function portalCorrectionForm(r){
 const keys=r.type==='Stage Report'?Object.keys(r.fields||{}):Array.from(new Set([...Object.keys(r.fields||{}),...fieldNames(r.type),'Remarks']));
 modal('Edit '+r.type+' · '+r.date,`<form id="portalCorrection"><p class="notice">This correction updates portal tables, PDFs and analysis. It is retained during sync. The original source Sheet / dedicated entry tab is unchanged.</p><div class="form-grid"><label>Date<input name="date" type="date" value="${esc(r.date)}" required></label><label>Shift<select name="shift">${option(['Day','Night','Daily'],r.shift)}</select></label>${keys.map((k,i)=>`<label>${esc(k)}<input name="field${i}" value="${esc(r.fields?.[k]??'')}"></label>`).join('')}<label class="full">Correction reason<textarea name="reason" required></textarea></label></div><button type="submit">Save correction</button></form>`);
 submit($('#portalCorrection'),async fd=>{const fields={};keys.forEach((k,i)=>fields[k]=fd.get('field'+i));await mutate('correctReport',{id:r.id,version:r.version,date:fd.get('date'),shift:fd.get('shift'),fields,reason:fd.get('reason')});message('Correction saved');});
}


async function boilerExcelForm(){
 modal('Import Daily Boiler Summary',`<form id="boilerSummaryUpload"><p>Only the Boiler Report tab is imported. All other tabs are ignored.</p><label>Excel file<input name="file" type="file" accept=".xlsx" required></label><label>Report date<input name="date" type="date" required></label><label>Operator (optional)<input name="Operator"></label><button type="submit">Read and preview summary</button><p data-save-status></p></form>`);
 const form=$('#boilerSummaryUpload'),file=form.elements.namedItem('file');file.onchange=()=>{const m=file.files[0]?.name.match(/(\d{2})_(\d{2})_(\d{4})/);if(m)form.elements.namedItem('date').value=m[3]+'-'+m[2]+'-'+m[1];};
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const chosen=file.files[0],date=form.elements.namedItem('date').value;const m=await import('./boiler-import.js?v=40');const record=parseSummarySheet(await m.readBoilerWorkbook(chosen,'Boiler Report'),date);record.fields.Operator=form.elements.namedItem('Operator').value;
 modal('Confirm Daily Boiler Summary',`<p>${esc(date)} · ${esc(chosen.name)} · 1 summary</p><div class="table-wrap"><table><thead><tr><th>Parameter</th><th>Standard</th><th>Actual</th><th>Remarks</th></tr></thead><tbody>${METRICS.map(([label,key])=>`<tr><td>${esc(label)}</td><td>${esc(record.fields['Standard: '+key])}</td><td>${esc(record.fields[key]||'Unavailable')}</td><td>${esc(record.fields['Remark: '+key])}</td></tr>`).join('')}</tbody></table></div><p>Only this summary is saved; hourly logs and water-test rows are not imported.</p><form id="boilerSummaryConfirm"><label><input type="checkbox" required>I checked summary values and date</label><button type="submit">Confirm — append summary</button><p data-save-status></p></form>`);
 submit($('#boilerSummaryConfirm'),async()=>{await api('importBoilerExcel',{summaryMode:true,records:[record],filename:chosen.name},true);$('#dialog').close();await load();message('Daily Boiler Summary saved to Google Sheet');});
 }catch(err){form.querySelector('[data-save-status]').textContent=err.message;}finally{button.disabled=false;}};
}

async function exportTaskReportPdf(){const button=$('#downloadTaskReportPdf');if(button)button.disabled=true;try{if(!taskReportRows.length)throw Error('Select a date range and show the report first.');const q=taskReportEmployeeSearch.trim().toLocaleLowerCase(),rows=taskReportRows.filter(r=>!q||String(r.employee||'').toLocaleLowerCase().includes(q));if(!rows.length)throw Error('No task rows match this employee search.');await ensurePdf();const {PDFDocument,StandardFonts,rgb}=globalThis.PDFLib,pdf=await PDFDocument.create(),font=await pdf.embedFont(StandardFonts.Helvetica),bold=await pdf.embedFont(StandardFonts.HelveticaBold);let page=pdf.addPage([842,595]),y=555;const draw=(txt,size=9,weight=false)=>{page.drawText(String(txt??'').replace(/[^\x20-\x7E]/g,'?').slice(0,150),{x:34,y,size,font:weight?bold:font,color:rgb(0.12,0.16,0.22)});};const newPage=()=>{page=pdf.addPage([842,595]);y=555;header();};const header=()=>{draw('Starish Portal · Employee Task Report',17,true);y-=24;draw('Date range: '+($('#taskReportFrom')?.value||'')+' to '+($('#taskReportTo')?.value||'')+'    Employee: '+(taskReportEmployeeSearch||'All employees'),10);y-=20;const total=rows.reduce((n,r)=>n+r.total,0),done=rows.reduce((n,r)=>n+r.complete,0),pending=rows.reduce((n,r)=>n+r.pending,0);draw('Tasks: '+total+'    Complete: '+done+'    Pending: '+pending+'    Efficiency: '+(total?Math.round(done/total*100):0)+'%',10,true);y-=25;draw('Date',9,true);draw('Employee',9,true);page.drawText('Task', {x:230,y,size:9,font:bold,color:rgb(.12,.16,.22)});page.drawText('Status', {x:585,y,size:9,font:bold,color:rgb(.12,.16,.22)});page.drawText('Pending reason', {x:665,y,size:9,font:bold,color:rgb(.12,.16,.22)});y-=15;page.drawLine({start:{x:34,y},end:{x:808,y},thickness:.6,color:rgb(.55,.6,.67)});y-=16;};header();for(const r of rows){for(const t of r.tasks||[]){if(y<42)newPage();draw(t.date||r.date,8);draw(r.employee,8);page.drawText(String(t.title||'').replace(/[^\x20-\x7E]/g,'?').slice(0,58),{x:230,y,size:8,font,color:rgb(.12,.16,.22)});page.drawText(String(t.status||'').replace(/[^\x20-\x7E]/g,'?').slice(0,12),{x:585,y,size:8,font,color:rgb(.12,.16,.22)});page.drawText(String(t.pendingReason||'').replace(/[^\x20-\x7E]/g,'?').slice(0,28),{x:665,y,size:8,font,color:rgb(.12,.16,.22)});y-=15;}}const bytes=await pdf.save(),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download='Starish_Task_Report_'+($('#taskReportFrom')?.value||'')+'_'+($('#taskReportTo')?.value||'')+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}catch(e){message(e.message);}finally{if(button)button.disabled=false;}}
